# CPS factorial: n! via continuation-passing style, evaluated at n=5 with the
# identity continuation. Purely deterministic computation (no random choices).

def cps_factorial(k, n):
    if n == 0:
        return k(1)
    else:
        return cps_factorial(lambda x: k(x * n), n - 1)

ANSWER = cps_factorial(lambda x: x, 5)

# CPS factorial extended for negative inputs. n < 0 invokes the error
# continuation; n == 0 delivers 1 to the success continuation; otherwise recurse
# on n-1 multiplying by n. Called with n = -1, identity success continuation, and
# a constant error continuation returning 'err'. Purely deterministic.


def total_cps_factorial(k, err, n):
    if n < 0:
        return err("cpsFactorial: n < 0!")
    elif n == 0:
        return k(1)
    else:
        return total_cps_factorial(lambda x: k(x * n), err, n - 1)


