def enum_marginal(model, n):
    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(
        model, lambda: None
    )["x"]
    sup = marg.enumerate_support()
    probs = marg.log_prob(sup).exp()
    out = {int(s): 0.0 for s in range(n)}
    for s, p in zip(sup.tolist(), probs.tolist()):
        out[int(s)] = p
    return out


