def literal_listener(utt_idx, goal):
    @pyro.infer.config_enumerate
    def model():
        st = pyro.sample("st", dist.Categorical(torch.ones(len(states))))
        vp = torch.stack([torch.tensor([val_neg_p[s], 1 - val_neg_p[s]]) for s in states])
        val = pyro.sample("val", dist.Categorical(vp[st]))
        ap = torch.stack([torch.tensor([float(x) for x in arousal_w[s]]) / sum(arousal_w[s])
                          for s in states])
        ar = pyro.sample("ar", dist.Categorical(ap[st]))
        # literalInterpretation: utterance === state
        pyro.factor("cond", torch.where(st == utt_idx, torch.tensor(0.0), torch.tensor(NEG)))
        return None

    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(model, lambda: None)
    if goal == "goalState":
        m = marg["st"]
        sup = m.enumerate_support()
        pr = m.log_prob(sup).exp()
        return {("state", states[int(i)]): p for i, p in zip(sup.tolist(), pr.tolist())}
    if goal == "goalValence":
