        sup = m.enumerate_support()
        pr = m.log_prob(sup).exp()
        return {("val", valences[int(i)]): p for i, p in zip(sup.tolist(), pr.tolist())}
    m = marg["ar"]
    sup = m.enumerate_support()
    pr = m.log_prob(sup).exp()
    return {("ar", arousals[int(i)]): p for i, p in zip(sup.tolist(), pr.tolist())}


