# Pragmatic listener: joint posterior over (state, valence, arousal) via exact
# enumeration of a single combined latent; the engine marginalizes.
def pragmatic_listener(utt_idx):
    combos = []
    for s in range(len(states)):
        for vi in range(2):
            for ai in range(len(arousals)):
                combos.append((s, vi, ai))
    sp_norm = (state_prior / state_prior.sum()).tolist()
    jp = []
    for (s, vi, ai) in combos:
        st = states[s]
        pv = val_neg_p[st] if vi == 0 else (1 - val_neg_p[st])
        aw = arousal_w[st]
        pa = aw[ai] / sum(aw)
        jp.append(sp_norm[s] * pv * pa)
    jp = torch.tensor(jp)
    score = torch.full((len(combos), 3), NEG)
    for j, (s, vi, ai) in enumerate(combos):
        val = valences[vi]
        ar = arousals[ai]
        for g in range(3):
            spk = speaker_logprobs(s, val, ar, goals[g])
            p = spk.get(utt_idx, 0.0)
            score[j, g] = math.log(p) if p > 0 else NEG

    @pyro.infer.config_enumerate
    def model():
        cf = pyro.sample("cf", dist.Categorical(jp))
        goal = pyro.sample("goal", dist.Categorical(goal_prior))
        pyro.factor("obs", score[cf, goal])
        return None

    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(model, lambda: None)
    m = marg["cf"]
    sup = m.enumerate_support()
    pr = m.log_prob(sup).exp()
    out = {}
    for j, p in zip(sup.tolist(), pr.tolist()):
        s, vi, ai = combos[int(j)]
        rec = {"state": states[s], "valence": valences[vi], "arousal": arousals[ai]}
        out[json.dumps(rec, sort_keys=True)] = p
    return out


