def uttCost(utt):
    return len(utt.split(" "))

def uttFitness(utt, obj):
    d = utt.split(" ")
    if len(d) > 1:
        return 0.0 if (obj["color"] == d[0] and obj["type"] == d[1]) else -100.0
    return 0.0 if obj["type"] == d[0] else -100.0

def _ctxkey(ctx):
    return tuple((o["color"], o["type"]) for o in ctx)

# Literal listener: uniform over the perceived context, factor by utterance fitness.
# Exact enumeration via Pyro's compute_marginals.
_L0_cache = {}
def L0(utt, perceivedContext):
    key = (utt, _ctxkey(perceivedContext))
    if key in _L0_cache:
        return _L0_cache[key]
    _fit = torch.tensor([uttFitness(utt, o) for o in perceivedContext])
    @pyro.infer.config_enumerate
    def m():
        idx = pyro.sample("obj", dist.Categorical(torch.ones(len(perceivedContext))))
        pyro.factor("fit", _fit[idx])
    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(m, lambda: None)
    _L0_cache[key] = marg["obj"]
    return _L0_cache[key]

# Speaker: utterance ~ exp(alpha * L0.score(target) - uttCost), inverting L0.
_S1_cache = {}
def S1(target, knownContext):
    key = ((target["color"], target["type"]), _ctxkey(knownContext))
    if key in _S1_cache:
        return _S1_cache[key]
    tidx = knownContext.index(target)
    L0s = [L0(u, knownContext) for u in possibleUtterances]
    _sc = torch.tensor([
        alpha * L0s[i].log_prob(torch.tensor(tidx)).item() - uttCost(possibleUtterances[i])
        for i in range(len(possibleUtterances))
    ])
    @pyro.infer.config_enumerate
    def m():
        uidx = pyro.sample("utt", dist.Categorical(torch.ones(len(possibleUtterances))))
        pyro.factor("util", _sc[uidx])
    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(m, lambda: None)
    _S1_cache[key] = marg["utt"]
    return _S1_cache[key]

