# RSA quantifier-scope model (English Expt 1, surface scope).
# Each RSA level is a SEPARATE, fully-computed and memoized Pyro enumeration.
# A level's only latent sample site is enumerated and its marginal is read with
# TraceEnum_ELBO.compute_marginals; the finished distribution is then fed into
# the next level as a fixed pyro.factor score table. No inference is ever run
# inside another level's active trace, and every sample site has a name unique
# to its level, so there is no site collision.

utterances = ["null", "not-two"]
states = [0, 1, 2]
scopes = ["surface", "inverse"]
QUDs = ["how many?", "all red?", "none red?"]
alpha = 1.0

state_logits = torch.zeros(len(states))   # ps:[1,1,1]
utt_logits = torch.zeros(len(utterances)) # ps:[1,1]
scope_logits = torch.zeros(len(scopes))   # ps:[1,1]
qud_logits = torch.zeros(len(QUDs))       # uniform


def cost(_u):
    return 1.0


def meaning(utterance, state, scope):
    if utterance == "not-two":
        if scope == "surface":
            return (state == 0) or (state == 1)
        return state == 0
    return True


def qud_fun(qud, state):
    if qud == "all red?":
        return ("bool", state == 2)
    if qud == "none red?":
        return ("bool", state == 0)
    return ("state", state)


def enum_marginal(model, site):
    # Run exact discrete enumeration over a single-latent model and return its
    # marginal as {support_index: prob}.
    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(
        model, lambda: None
    )[site]
    sup = marg.enumerate_support()
    probs = marg.log_prob(sup).exp()
    return {int(sup[i].item()): float(probs[i].item()) for i in range(sup.shape[0])}


# ---- Literal listener L0: posterior over qState given (utterance, scope, QUD) ----
L0_cache = {}


def literal_listener(utterance, scope, qud):
    key = (utterance, scope, qud)
    if key in L0_cache:
        return L0_cache[key]
    ok = torch.tensor([meaning(utterance, st, scope) for st in states], dtype=torch.bool)

    @pyro.infer.config_enumerate
    def model():
        s = pyro.sample("L0_state", dist.Categorical(logits=state_logits))
        pyro.factor("L0_ev", torch.where(ok[s], torch.tensor(0.0), torch.tensor(float("-inf"))))
        return s

    state_post = enum_marginal(model, "L0_state")
    # push the inferred state posterior forward through the QUD projection
    d = defaultdict(float)
    for si, p in state_post.items():
        d[qud_fun(qud, states[si])] += p
    L0_cache[key] = dict(d)
    return L0_cache[key]


