def make_model(ret):
    @pyro.infer.config_enumerate
    def model():
        sprinkler = pyro.sample('sprinkler', dist.Bernoulli(0.5)).bool()
        rain = pyro.sample('rain', dist.Bernoulli(0.3)).bool()
        wet = sprinkler | rain
        pyro.factor('wet', torch.where(wet, torch.tensor(0.0), torch.tensor(float('-inf'))))
        return ret(rain, sprinkler)
    return model


def marginal_bool(site, ret):
    model = make_model(ret)
    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(model, lambda: None)
    m = marg[site]
    sup = m.enumerate_support()
    probs = m.log_prob(sup).exp()
    out = {}
    for v, p in zip(sup.tolist(), probs.tolist()):
        out[bool(v)] = out.get(bool(v), 0.0) + p
    return out


