# Recursive geometric process: each step a fair coin decides 0 vs 1 + recurse.
def geometric(trial):
    if bool(pyro.sample(f"f{trial}_0", dist.Bernoulli(0.5))):
        return 0
    n = 1
    i = 1
    while True:
        if bool(pyro.sample(f"f{trial}_{i}", dist.Bernoulli(0.5))):
            return n
        n += 1
        i += 1


