# Number-game concept learning. Hypothesis space = 50/50 mixture of rule
# concepts (multiples_of_N, powers_of_N for N in 1..11, evens, odds) and
# interval concepts (a..b, 1<=a<b<=20). Size-principle likelihood. Examples
# [3, 10]; test query 12. Posterior over (hypothesis, in-set(12)) via exact
# enumeration.

maxNumber = 20

def gen_evens():
    return sorted(set(v for v in range(1, maxNumber + 1) if v % 2 == 0))

def gen_odds():
    return sorted(set(v for v in range(1, maxNumber + 1) if (v + 1) % 2 == 0))

def gen_multiples(base):
    return sorted(set(v for v in (base * k for k in range(1, maxNumber + 1))
                      if 1 <= v <= maxNumber))

def gen_powers(base):
    return sorted(set(v for v in (base ** e for e in range(maxNumber))
                      if 1 <= v <= maxNumber))

def get_set(rule):
    parts = rule.split("_")
    if parts[0] == "multiples":
        return gen_multiples(int(parts[2]))
    if parts[0] == "powers":
        return gen_powers(int(parts[2]))
    if rule == "evens":
        return gen_evens()
    if rule == "odds":
        return gen_odds()
    if parts[0] == "interval":
        return list(range(int(parts[1]), int(parts[2]) + 1))
    raise ValueError(rule)

rule_hyps = ([f"multiples_of_{b}" for b in range(1, 12)] +
             [f"powers_of_{b}" for b in range(1, 12)] + ["evens", "odds"])
interval_hyps = [f"interval_{a}_{b}"
                 for a in range(1, maxNumber + 1) for b in range(a + 1, maxNumber + 1)]
n_rules = len(rule_hyps)
n_intervals = len(interval_hyps)

# Flatten the 50/50 mixture into one categorical prior over all hypotheses:
# 0.5 mass split uniformly within the rule class, 0.5 within the interval class.
all_hyps = rule_hyps + interval_hyps
prior = torch.cat([
    torch.full((n_rules,), 0.5 / n_rules),
    torch.full((n_intervals,), 0.5 / n_intervals),
])

examples = [3, 10]
test_query = 12

# Size-principle log-likelihood of the examples per hypothesis:
# each example drawn uniformly from the concept extension.
def loglik(hyp):
    s = set(get_set(hyp))
    if any(ex not in s for ex in examples):
        return float("-inf")
    return len(examples) * (-math.log(len(s)))

logliks = torch.tensor([loglik(h) for h in all_hyps])

@pyro.infer.config_enumerate
def model():
    h = pyro.sample("hyp", dist.Categorical(prior))
    pyro.factor("lik", logliks[h])
    return h

marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(
    model, lambda: None
)
post = marg["hyp"].probs

agg = {}
for i, hyp in enumerate(all_hyps):
    pr = post[i].item()
    if pr <= 0.0:
        continue
    tqr = test_query in set(get_set(hyp))
    key = json.dumps({"hypothesis": hyp, "testQueryResponse": tqr}, sort_keys=True)
    agg[key] = agg.get(key, 0.0) + pr

ANSWER = agg

# Number-game concept learning over an enumerable hypothesis space.
# Prior: 50/50 mixture of rule concepts (24) and interval concepts (190).
# Likelihood: size principle (each example uniform over the concept extension).
# We enumerate the hypothesis with Pyro's exact discrete inference
# (config_enumerate + TraceEnum_ELBO.compute_marginals) and read the expected
# membership probability for each integer 1..20 off the posterior over concepts.
#
# NOTE: the WebPPL GT deliberately deviates from the textbook ranges (it keeps
# integers in [1, maxNumber]); we reproduce the GT ranges exactly here and do
# NOT restore textbook behavior.

maxNumber = 20

def filterByInRange(values):
    seen = []
    for v in values:
        if 1 <= v <= maxNumber and v not in seen:
            seen.append(v)
    return seen

def genEvens():
    return [v for v in range(1, maxNumber + 1) if v % 2 == 0]

def genOdds():
    return [v for v in range(1, maxNumber + 1) if (v + 1) % 2 == 0]

def genMultiples(base):
    return filterByInRange([base * v for v in range(1, maxNumber + 1)])

def genPowers(base):
    # exponents start at 0 (range(maxNumber) = 0..19), so 1 is always included
    return filterByInRange([base ** v for v in range(maxNumber)])

def genSetFromInterval(a, b):
    return list(range(a, b + 1))

# Build the hypothesis space: each entry is (label, frozenset of its extension).
rule_specs = []
for base in range(1, 12):
    rule_specs.append(("multiples_of_" + str(base), genMultiples(base)))
for base in range(1, 12):
    rule_specs.append(("powers_of_" + str(base), genPowers(base)))
rule_specs.append(("evens", genEvens()))
rule_specs.append(("odds", genOdds()))

interval_specs = []
for s in range(1, maxNumber + 1):
    for e in range(s + 1, maxNumber + 1):
        interval_specs.append(("interval_" + str(s) + "_" + str(e), genSetFromInterval(s, e)))

n_rules = len(rule_specs)
n_intervals = len(interval_specs)

hypotheses = [(lab, set(ext)) for lab, ext in rule_specs] + \
             [(lab, set(ext)) for lab, ext in interval_specs]
n_hyp = len(hypotheses)

# Marginal prior over hypotheses: 0.5 split over rules, 0.5 split over intervals.
prior = torch.zeros(n_hyp)
for i in range(n_rules):
    prior[i] = 0.5 / n_rules
for j in range(n_intervals):
    prior[n_rules + j] = 0.5 / n_intervals

examples = [3, 6, 9]

# Size-principle log-likelihood of the examples for each hypothesis.
loglik = torch.full((n_hyp,), float("-inf"))
for i, (lab, ext) in enumerate(hypotheses):
    size = len(ext)
    if size == 0:
        continue
    if all(x in ext for x in examples):
        loglik[i] = -len(examples) * math.log(size)

@pyro.infer.config_enumerate
def model():
    h = pyro.sample("h", dist.Categorical(prior))
    pyro.factor("size_principle", loglik[h])
    return h

marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(model, lambda: None)["h"]
sup = marg.enumerate_support()
post_probs = marg.log_prob(sup).exp()
posterior = torch.zeros(n_hyp)
for s, p in zip(sup, post_probs):
    posterior[int(s.item())] = p

# Membership matrix: member[i][q] = 1 if integer (q+1) is in hypothesis i.
queries = genSetFromInterval(1, maxNumber)
ANSWER = []
for q in queries:
    expected = 0.0
    for i, (lab, ext) in enumerate(hypotheses):
        if q in ext:
            expected += float(posterior[i].item())
    ANSWER.append(expected)
